  "items": [
    {
      "stem": "一个圆的半径是3厘米，它的周长是多少厘米？（π取3.14）",
      "answer": "18.84",
      "solution": "根据圆的周长公式 C=2πr，代入数据得：2 × 3.14 × 3 = 18.84（厘米）。"
    },
    {
      "stem": "一个圆的直径是10分米，它的面积是多少平方分米？（π取3.14）",
      "answer": "78.5",
      "solution": "首先求半径 r = d ÷ 2 = 10 ÷ 2 = 5（分米）。根据圆的面积公式 S=πr²，代入数据得：3.14 × 5² = 3.14 × 25 = 78.5（平方分米）。"
    },
    {
      "stem": "用一根长12.56米的绳子围成一个圆，这个圆的半径是多少米？（π取3.14）",
      "answer": "2",
      "solution": "绳子的长度即为圆的周长。根据公式 r = C ÷ (2π)，代入数据得：12.56 ÷ (2 × 3.14) = 12.56 ÷ 6.28 = 2（米）。"
    },
    {
      "stem": "一个圆形花坛的周长是18.84米，它的面积是多少平方米？（π取3.14）",
      "answer": "28.26",
      "solution": "先求半径：r = 18.84 ÷ 3.14 ÷ 2 = 3（米）。再求面积：S = 3.14 × 3² = 3.14 × 9 = 28.26（平方米）。"
    },
    {
      "stem": "在一个边长为4厘米的正方形内画一个最大的圆，这个圆的面积是多少平方厘米？（π取3.14）",
      "answer": "12.56",
      "solution": "正方形内最大圆的直径等于正方形的边长，即 d=4厘米，所以半径 r=2厘米。面积 S = 3.14 × 2² = 3.14 × 4 = 12.56（平方厘米）。"
    }
  ]
}
